begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
select has_function('public','complete_service_tour',array[]::text[],'account-level guide completion exists');
select has_function('public','morning_push_candidates',array['timestamp with time zone','uuid'],'morning reminders use the existing worker');
insert into auth.users(id) values('a9990000-0000-4000-8000-000000000001');
insert into profiles(id,display_name,consented_at,timezone) values('a9990000-0000-4000-8000-000000000001','Fixture',now(),'UTC');
insert into families(id,name) values('b9990000-0000-4000-8000-000000000001','Fixture');
insert into family_members(family_id,user_id,role) values('b9990000-0000-4000-8000-000000000001','a9990000-0000-4000-8000-000000000001','owner');
insert into children(id,family_id,name,sex,birth_date) values('c9990000-0000-4000-8000-000000000001','b9990000-0000-4000-8000-000000000001','Fixture','female',current_date-100);
insert into signup_agreements(user_id,kind,version,interface_locale) select 'a9990000-0000-4000-8000-000000000001',kind,version,'ko' from signup_document_versions where is_current;
insert into signup_privacy_choices(user_id,version,locale,child_information,authority,health,public_sharing,neighborhood) values('a9990000-0000-4000-8000-000000000001',current_signup_privacy_version(),'ko',true,true,true,false,false);
insert into child_privacy_consents(child_id,accepted_by,version,child_information,authority,health,public_sharing,neighborhood) values('c9990000-0000-4000-8000-000000000001','a9990000-0000-4000-8000-000000000001',current_signup_privacy_version(),true,true,true,false,false);
insert into notification_preferences(user_id) values('a9990000-0000-4000-8000-000000000001');
select ok((select feeding_enabled and not playground_enabled and not schedule_enabled from notification_preferences where user_id='a9990000-0000-4000-8000-000000000001'),'only feeding defaults on for new preferences');
insert into web_push_subscriptions(id,user_id,endpoint,p256dh,auth_key,locale,created_at) values('d9990000-0000-4000-8000-000000000001','a9990000-0000-4000-8000-000000000001','https://fcm.googleapis.com/fcm/send/schedule-test',repeat('B',87),repeat('A',22),'ko','2026-11-03 00:00+00');
insert into events(child_id,title,date,created_by) values('c9990000-0000-4000-8000-000000000001','Private plan','2026-11-04','a9990000-0000-4000-8000-000000000001');
insert into tasks(child_id,title,service,due_date,created_by) values('c9990000-0000-4000-8000-000000000001','Private task','general','2026-11-04','a9990000-0000-4000-8000-000000000001');
select public.morning_push_at('a9990000-0000-4000-8000-000000000001','2026-11-04','UTC') as morning \gset
select is((select count(*)::int from morning_push_candidates(:'morning')),0,'schedule summaries require opt-in');
update notification_preferences set schedule_enabled=true,schedule_enabled_at='2026-11-03 00:00+00';
select is((select item_count::int from morning_push_candidates(:'morning')),2,'one summary counts events and unfinished tasks');
select is((select count(*)::int from morning_push_candidates('2026-11-04 07:59+00')),0,'not sent before 8 am');
select is((select count(*)::int from morning_push_candidates(:'morning'::timestamptz+interval '10 minutes')),0,'old reminders are not backfilled');
select ok(:'morning'::timestamptz>='2026-11-04 08:00+00' and :'morning'::timestamptz<'2026-11-04 08:10+00','stable user slot spreads within ten minutes');
select is((select count(*)::int from morning_push_candidates(:'morning','d9990000-0000-4000-8000-000000000001')),1,'validation can select just its device');
select is((select count(*)::int from morning_push_candidates(:'morning','d9990000-0000-4000-8000-000000000002')),0,'targeted validation excludes other devices');
update profiles set timezone='Asia/Seoul';
select is((select item_count::int from morning_push_candidates(public.morning_push_at('a9990000-0000-4000-8000-000000000001','2026-11-04','Asia/Seoul'))),2,'8 am follows the account time zone');
select is((select count(*)::int from morning_push_candidates(:'morning')),0,'server UTC 8 am is not used for Seoul users');
update profiles set timezone='UTC';
update tasks set status='done';
select is((select item_count::int from morning_push_candidates(:'morning')),1,'completed tasks are excluded');
delete from events;
select is((select count(*)::int from morning_push_candidates(:'morning')),0,'days without plans are silent');
insert into events(child_id,title,date,created_by) values('c9990000-0000-4000-8000-000000000001','Private plan','2026-11-04','a9990000-0000-4000-8000-000000000001');
update notification_preferences set schedule_enabled_at='2026-11-04 08:01+00';
select is((select count(*)::int from morning_push_candidates(:'morning'::timestamptz+interval '2 minutes')),0,'enabling after 8 am starts the next day');
update notification_preferences set schedule_enabled_at='2026-11-03 00:00+00';
insert into schedule_push_deliveries(subscription_id,day,scheduled_at) values('d9990000-0000-4000-8000-000000000001','2026-11-04','2026-11-04 08:00+00');
select throws_ok($$insert into schedule_push_deliveries(subscription_id,day,scheduled_at) values('d9990000-0000-4000-8000-000000000001','2026-11-04','2026-11-04 08:00+00')$$,'23505',null,'one delivery per day and device');
delete from feeding_push_config;
insert into feeding_push_config(public_key,worker_url,token_secret_id) values(repeat('B',87),'https://example.invalid',(select vault.create_secret(repeat('a',64),'schedule-test-'||gen_random_uuid())));
select throws_ok($$select * from claim_schedule_push('wrong')$$,'42501','forbidden','worker token is required');
select lives_ok($$select * from claim_schedule_push(repeat('a',64))$$,'worker can claim without SQL ambiguity');
select set_config('request.jwt.claims','{"sub":"a9990000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*)::int from my_schedule_items('2026-11-04')),1,'notification opens the caller’s accessible agenda');
select complete_service_tour();select complete_service_tour();
select ok((select service_tour_completed_at is not null from profiles where id=auth.uid()),'guide completion persists idempotently on the account');
select ok(not has_function_privilege('authenticated','public.morning_push_candidates(timestamptz,uuid)','execute'),'browser cannot inspect other reminder candidates');
select throws_ok($$select * from schedule_push_deliveries$$,'42501',null,'delivery records stay private');
reset role;
delete from family_members;
select is((select count(*)::int from morning_push_candidates(:'morning')),0,'revoked access suppresses summaries');
insert into family_members(family_id,user_id,role) values('b9990000-0000-4000-8000-000000000001','a9990000-0000-4000-8000-000000000001','owner');
create or replace function public.morning_push_at(p_user uuid,p_day date,p_timezone text) returns timestamptz language sql stable set search_path='' as $$ select now()-interval '1 minute'; $$;
delete from web_push_subscriptions where user_id<>'a9990000-0000-4000-8000-000000000001';
delete from schedule_push_deliveries;
update notification_preferences set schedule_enabled=true,schedule_enabled_at=current_date-interval '1 day' where user_id='a9990000-0000-4000-8000-000000000001';
update web_push_subscriptions set created_at=current_date-interval '1 day';
insert into events(child_id,title,date,created_by) values('c9990000-0000-4000-8000-000000000001','Clock-controlled plan',current_date,'a9990000-0000-4000-8000-000000000001');
create temporary table schedule_leased as select * from claim_schedule_push(repeat('a',64));
select is((select count(*)::int from schedule_leased),1,'eligible device is leased');
select is((select count(*)::int from claim_schedule_push(repeat('a',64))),0,'a live lease is not claimed twice');
select ok((select validate_schedule_push(id,lease_token) from schedule_leased),'a current lease validates');
select finish_schedule_push(id,gen_random_uuid(),'sent') from schedule_leased;
select is((select status from schedule_push_deliveries),'sending','stale token cannot finish another lease');
update notification_preferences set schedule_enabled=false where user_id='a9990000-0000-4000-8000-000000000001';
select ok(not (select validate_schedule_push(id,lease_token) from schedule_leased),'opt-out after claim cancels send');
select finish_schedule_push(id,lease_token,'cancelled') from schedule_leased;
select is((select status from schedule_push_deliveries),'cancelled','valid lease acknowledges cancellation');
select * from finish();
rollback;
